from pathlib import Path
import zipfile, shutil, tempfile, os
import xml.etree.ElementTree as ET
from copy import deepcopy

path = Path('/home/user/Student_Level_Fill_Blank.xlsx')
backup = path.with_suffix(path.suffix + '.bak')
if not backup.exists():
    shutil.copy2(path, backup)

NS_MAIN = 'http://schemas.openxmlformats.org/spreadsheetml/2006/main'
NS_REL = 'http://schemas.openxmlformats.org/officeDocument/2006/relationships'
NS_PKG_REL = 'http://schemas.openxmlformats.org/package/2006/relationships'
ET.register_namespace('', NS_MAIN)
ET.register_namespace('r', NS_REL)

def q(ns, tag):
    return f'{{{ns}}}{tag}'

def col_to_num(col):
    n = 0
    for ch in col:
        n = n * 26 + ord(ch) - 64
    return n

def cell_col(ref):
    return ''.join(ch for ch in ref if ch.isalpha())

def cell_has_value(c):
    return c.find(q(NS_MAIN, 'v')) is not None or c.find(q(NS_MAIN, 'is')) is not None or c.get('t') == 'str'

def cell_blank(c):
    return c is None or not cell_has_value(c)

with zipfile.ZipFile(path, 'r') as zin:
    files = {name: zin.read(name) for name in zin.namelist()}

# Resolve the first worksheet from workbook relationships rather than assuming a path.
workbook = ET.fromstring(files['xl/workbook.xml'])
sheets = workbook.find(q(NS_MAIN, 'sheets'))
first_sheet = sheets.find(q(NS_MAIN, 'sheet'))
rid = first_sheet.get(q(NS_REL, 'id'))
rels = ET.fromstring(files['xl/_rels/workbook.xml.rels'])
target = None
for rel in rels.findall(q(NS_PKG_REL, 'Relationship')):
    if rel.get('Id') == rid:
        target = rel.get('Target')
        break
if target is None:
    raise RuntimeError('Could not resolve first worksheet')
sheet_path = 'xl/' + target.lstrip('/') if not target.startswith('xl/') else target

root = ET.fromstring(files[sheet_path])
sheet_data = root.find(q(NS_MAIN, 'sheetData'))
rows = {int(row.get('r')): row for row in sheet_data.findall(q(NS_MAIN, 'row'))}

# Ensure rows 1-30 exist.
for r in range(1, 31):
    if r not in rows:
        row = ET.Element(q(NS_MAIN, 'row'), {'r': str(r)})
        rows[r] = row
        inserted = False
        for idx, existing in enumerate(list(sheet_data)):
            if existing.tag == q(NS_MAIN, 'row') and int(existing.get('r')) > r:
                sheet_data.insert(idx, row)
                inserted = True
                break
        if not inserted:
            sheet_data.append(row)

changed = []
for r in range(1, 31):
    row = rows[r]
    cells = {c.get('r'): c for c in row.findall(q(NS_MAIN, 'c'))}
    for col in ['B', 'C', 'D', 'E']:
        ref = f'{col}{r}'
        cur = cells.get(ref)
        if r == 1 or not cell_blank(cur):
            continue
        above = rows[r-1].find(f\"{q(NS_MAIN, 'c')}[@r='{col}{r-1}']\")
        if cell_blank(above):
            continue
        new_cell = deepcopy(above)
        new_cell.set('r', ref)
        # Leave formulas out; this task asks for the displayed value from above.
        f = new_cell.find(q(NS_MAIN, 'f'))
        if f is not None:
            new_cell.remove(f)
        # Insert in column order within row.
        inserted = False
        for idx, existing in enumerate(list(row)):
            if existing.tag == q(NS_MAIN, 'c') and col_to_num(cell_col(existing.get('r'))) > col_to_num(col):
                row.insert(idx, new_cell)
                inserted = True
                break
        if not inserted:
            row.append(new_cell)
        changed.append(ref)

files[sheet_path] = ET.tostring(root, encoding='utf-8', xml_declaration=True)

tmp = path.with_suffix(path.suffix + '.tmp')
with zipfile.ZipFile(tmp, 'w', compression=zipfile.ZIP_DEFLATED) as zout:
    for name, data in files.items():
        zout.writestr(name, data)
os.replace(tmp, path)
print(f'filled {len(changed)} cells')
print(' '.join(changed))
